// The Core Report's census data: every downtown core and its region in each
// census year sdsc-data has pulled (2001 and 2021 today).
//
// The three CSVs are generated by `npm run core-series` from sdsc-data's
// downtown_vs_cma_comparison.csv and boundary files. Re-run it whenever
// sdsc-data publishes new outputs; new downtowns and census years flow through.

import { csvParse } from 'd3';
// Imported as raw text and parsed here: a third the size of the row objects
// the CSV plugin would otherwise inline.
import citiesRaw from '../lib/data/coredata/coreCities.csv?raw';
import seriesRaw from '../lib/data/coredata/coreSeries.csv?raw';
import variablesRaw from '../lib/data/coredata/coreVariables.csv?raw';

const THEME_LABELS = {
	overall_growth: 'Growth',
	migration_and_imm: 'Migration',
	housing_supply: 'Housing',
	Demographics: 'People & work'
};

// Missing values stay missing rather than reading as zero.
function num(text) {
	if (text == null || text === '' || text === 'NA') return null;
	const value = Number(text);
	return Number.isFinite(value) ? value : null;
}

const slug = (text) =>
	String(text ?? '')
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, '-')
		.replace(/^-|-$/g, '');

/** Key for one census variable within a profile: `indicator|variable_name`. */
export const variableKey = (indicator, variable) => `${indicator}|${variable}`;

const seriesRows = csvParse(seriesRaw);
const variableRows = csvParse(variablesRaw);
const cityRows = csvParse(citiesRaw);

/** Census years present in the data, oldest first. */
export const CENSUS_YEARS = seriesRows.columns
	.map((column) => Number(column.match(/^v_(\d{4})_dt$/)?.[1]))
	.filter(Boolean)
	.sort((a, b) => a - b);

export const LATEST_YEAR = CENSUS_YEARS.at(-1);

function emptyProfiles() {
	return Object.fromEntries(CENSUS_YEARS.map((year) => [year, {}]));
}

/**
 * One entry per downtown. `cmaKey`/`cmaName` name its region (several
 * downtowns can share one). `downtown` and `cma` each hold a profile per census
 * year, and a profile maps `variableKey(indicator, variable)` to
 * `{ value, percent }`: the count (or average, for income), or its share of
 * the indicator's total, 0-100.
 *
 * `downtownYears` lists the census years with usable downtown figures; earlier
 * years are left out where that census's areas spilled past the downtown.
 */
export const CITIES = cityRows.map((row) => ({
	key: row.key,
	name: row.name,
	province: row.province,
	cmaKey: row.cma_key || null,
	cmaName: row.cma_name || null,
	downtownYears: row.dt_years.split(' ').map(Number),
	downtown: emptyProfiles(),
	cma: emptyProfiles()
}));

const cityByKey = new Map(CITIES.map((city) => [city.key, city]));
const variableById = new Map(variableRows.map((row) => [row.id, row]));

for (const row of seriesRows) {
	const city = cityByKey.get(row.city);
	const variable = variableById.get(row.variable);
	if (!city || !variable) continue;
	const key = variableKey(variable.indicator, variable.variable_name);
	for (const year of CENSUS_YEARS) {
		for (const [geo, suffix] of [
			['downtown', 'dt'],
			['cma', 'cma']
		]) {
			const value = num(row[`v_${year}_${suffix}`]);
			city[geo][year][key] =
				variable.field === 'percent' ? { value: null, percent: value } : { value, percent: null };
		}
	}
}

// Population density, people per km², added to each profile under
// `variableKey('Density', 'Population density')`. Downtown boundaries don't
// change between censuses, so a downtown's area serves every year. CMA land
// areas are Statistics Canada's for one boundary year only (CMAs are redrawn
// each census), so regions have no density in other years. Not every
// downtown or region has an area yet.
const POPULATION = variableKey('Population', 'Population');
const DENSITY = variableKey('Density', 'Population density');

function setDensity(profile, area) {
	const population = profile[POPULATION]?.value;
	profile[DENSITY] = {
		value: population != null && area ? population / area : null,
		percent: null
	};
}

for (const row of cityRows) {
	const city = cityByKey.get(row.key);
	const cmaYear = Number(row.cma_area_year);
	for (const year of CENSUS_YEARS) {
		setDensity(city.downtown[year], num(row.downtown_km2));
		setDensity(city.cma[year], year === cmaYear ? num(row.cma_km2) : null);
	}
}

// Comparability caveats by indicator, from setting the two censuses'
// definitions side by side (coreVariables.csv).
const INDICATOR_NOTES = {
	'Commute Mode':
		'Counts each person’s main mode only, among people who travel to work: it leaves out people working from home and a small “other method” group. The 2021 Census was taken in May 2021, during the COVID-19 pandemic.',
	'Commute Duration':
		'Among people who travel to work. The 2021 Census was taken in May 2021, during the COVID-19 pandemic.',
	Occupation:
		'Occupation groups changed between censuses: 2021 uses NOC 2021, which moved middle managers out of “management” into the fields they manage, so management in particular does not compare with 2001.',
	'Generational Status':
		'2001 counts people aged 15 and over; 2021 counts everyone in private households, so the two years are not strictly comparable.',
	'Employment Income': 'The 2021 Census asked about income in 2020, the first year of the pandemic.'
};

const definitionRows = new Map(
	variableRows.map((row) => [variableKey(row.indicator, row.variable_name), row])
);

/**
 * What a measure is in each census, for one or more variables of one
 * indicator (several are added together): Statistics Canada's labels for what
 * is counted, the indicator's total it is a share of (if any), the census
 * vectors behind it, and any caveat on comparing years.
 */
export function defineMeasure(indicator, variables) {
	const rows = variables.map((v) => definitionRows.get(variableKey(indicator, v))).filter(Boolean);
	return {
		years: CENSUS_YEARS.map((year) => ({
			year,
			counts: rows.map((row) => row[`label_${year}`]).filter(Boolean),
			universe: rows[0]?.[`universe_${year}`] || null,
			codes: rows.flatMap((row) => row[`codes_${year}`].split(' ')).filter(Boolean)
		})).filter((entry) => entry.counts.length),
		note: INDICATOR_NOTES[indicator] ?? null
	};
}

/**
 * Every census variable, grouped theme → indicator → variable, for the
 * "every census measure" module's pickers. Shares are plotted wherever the
 * pipeline computed one, because they compare fairly as populations grow;
 * other variables use the raw value.
 */
export const THEMES = (() => {
	const themes = new Map();
	for (const row of variableRows) {
		if (!themes.has(row.theme)) {
			themes.set(row.theme, {
				key: slug(row.theme),
				label: THEME_LABELS[row.theme] ?? row.theme,
				indicators: new Map()
			});
		}
		const indicators = themes.get(row.theme).indicators;
		if (!indicators.has(row.indicator)) {
			indicators.set(row.indicator, {
				key: `${slug(row.theme)}--${slug(row.indicator)}`,
				label: row.indicator,
				variables: []
			});
		}
		indicators.get(row.indicator).variables.push(describeVariable(row));
	}

	return [...themes.values()].map((theme) => ({
		...theme,
		indicators: [...theme.indicators.values()]
	}));
})();

function describeVariable({ indicator, variable_name: name, field }) {
	const key = variableKey(indicator, name);
	const hasShare = field === 'percent';
	const isIncome = /average/i.test(name) && /income/i.test(name);

	// "Household Size: 1 person" reads as "1 person" under its indicator.
	const prefix = `${indicator}: `;
	return {
		key: `${slug(indicator)}--${slug(name)}`,
		label: name.startsWith(prefix) ? name.slice(prefix.length) : name,
		title: name,
		indicator,
		get: (profile) => profile?.[key]?.[field] ?? null,
		definition: defineMeasure(indicator, [name]),
		format: hasShare ? 'pct' : isIncome ? 'money' : 'int',
		// Raw counts run from a few hundred downtown residents to millions in a
		// region, so they need a log axis; shares and incomes don't.
		scale: hasShare || isIncome ? 'lin' : 'log',
		zeroFloor: hasShare,
		nominalDollars: isIncome
	};
}

/** Census years in which at least one downtown has a value for `get`. */
export function yearsWithData(get) {
	return CENSUS_YEARS.filter((year) => CITIES.some((city) => get(city.downtown[year]) != null));
}

/** Downtowns whose figures for `year` were left out (boundary mismatch). */
export const missingDowntowns = (year) => CITIES.filter((c) => !c.downtownYears.includes(year));
